use std::{env,fs,path::{Path,PathBuf}};
use noworodek::{extract_functions,CodeAtomRegistry,CodeLanguage,Qwen3CoderTokenizer};
fn lang(p:&Path)->Option<CodeLanguage>{match p.extension().and_then(|x|x.to_str()).unwrap_or_default(){"rs"=>Some(CodeLanguage::Rust),"c"|"h"|"cc"|"cpp"|"cxx"|"hpp"|"hh"|"hxx"=>Some(CodeLanguage::Cpp),_=>None}}
fn collect(root:&Path,out:&mut Vec<PathBuf>)->std::io::Result<()>{for e in fs::read_dir(root)?{let p=e?.path();if p.is_dir(){collect(&p,out)?}else if lang(&p).is_some(){out.push(p)}}Ok(())}
fn main()->Result<(),Box<dyn std::error::Error>>{let root=env::args().nth(1).or_else(||env::var("CODE_DICTIONARY_ROOT").ok()).ok_or("usage: noworodek-code-dictionary-ingest <source-root> (or CODE_DICTIONARY_ROOT)")?;let tp=env::args().nth(2).or_else(||env::var("QWEN_TOKENIZER_JSON").ok()).ok_or("usage: noworodek-code-dictionary-ingest <source-root> <qwen-tokenizer.json> (or QWEN_TOKENIZER_JSON)")?;let root=PathBuf::from(root);let tok=Qwen3CoderTokenizer::from_file(tp)?;let mut files=Vec::new();collect(&root,&mut files)?;files.sort();let mut reg=CodeAtomRegistry::new();let(mut scanned,mut parsed,mut funcs,mut ins,mut dup,mut fail,mut toks)=(0,0,0,0,0,0,0);println!("NOWORODEK CODE DICTIONARY INGEST V1");println!("root={}",root.display());println!("tokenizer={} revision={} vocab={}",tok.model_id(),tok.revision(),tok.vocab_size());for p in files{scanned+=1;let src=match fs::read_to_string(&p){Ok(x)=>x,Err(_)=>{fail+=1;continue}};let Some(l)=lang(&p)else{continue};let atoms=match extract_functions(&tok,l,&src){Ok(x)=>x,Err(_)=>{fail+=1;continue}};parsed+=1;funcs+=atoms.len();for a in atoms{toks+=a.token_ids.len();match reg.insert(a.atom){Ok(true)=>ins+=1,Ok(false)=>dup+=1,Err(_)=>fail+=1}}}println!("files_scanned={scanned}");println!("files_parsed={parsed}");println!("functions_detected={funcs}");println!("atoms_inserted={ins}");println!("duplicates={dup}");println!("registry_len={}",reg.len());println!("qwen_tokens_total={toks}");println!("failures={fail}");println!("RESULT bulk_external_code_memory=true training_not_run=true next_stage=curriculum_sampling+backprop");Ok(())}
